@Test
@Transactional
void 다른_사람() {
    SecurityContextHolder.getContext().setAuthentication(
            new UsernamePasswordAuthenticationToken("kwanhyun", null, List.of()));
    Member m = memberRepository.save(new Member("m2", 10));
    em.flush();

    SecurityContextHolder.getContext().setAuthentication(
            new UsernamePasswordAuthenticationToken("admin", null, List.of()));
    m.setUsername("관리자가 고침");
    em.flush();

    System.out.println("등록자: " + m.getCreatedBy());
    System.out.println("수정자: " + m.getLastModifiedBy());
}

