@Test
@Transactional
void 호출_횟수() {
    System.out.println("--- 저장 ---");
    Member m = memberRepository.save(new Member("m5", 10));
    em.flush();
    System.out.println("--- 수정 ---");
    m.setUsername("고침");
    em.flush();
    System.out.println("--- 조회 ---");
    em.clear();
    memberRepository.findById(m.getId());
}

